"""Create an isolated sensitivity runner from sealed v3; never edit original jobs."""
import json,shutil,hashlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];OLD=ROOT/'studies/20261105-gdi-masked-pretrain-v3';HERE=ROOT/'studies/20261105-normal-label-sensitivity'
def read(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def save(p,v):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(v,indent=2)+'\n',encoding='utf-8')
assert not HERE.exists();HERE.mkdir();shutil.copytree(OLD/'bundle',HERE/'bundle',ignore=shutil.ignore_patterns('__pycache__','*.pyc','manifest.json'))
conds={name:dict(label=label,weight=weight) for name,label,weight in [('B_y90_w1_adult',90,1),('B_y100_w1_adult',100,1),('B_y110_w1_adult',110,1),('B_y100_w025_adult',100,.25),('B_y100_w4_adult',100,4)]}
p=read(OLD/'bundle/protocol.json');p.update(study='normal-label-sensitivity-20261105',conditions=list(conds),sensitivity=conds,expected_gdi_fits=40,expected_pretraining_fits=0,revision='Same v3 B_adult code except assumed target and multiplier on external loss terms; baseline control reused from v3',training='Same sample order, count, seed, epochs, Stanford coefficients across five sensitivity arms; no pretraining',main_conditions=[k for k in conds if k!='B_y100_w1_adult'])
save(HERE/'bundle/protocol.json',p)
path=HERE/'bundle/experiment.py';s=path.read_text()
s=s.replace("config=read(HERE/(family+'-original.json'));seed=", "variant=protocol['sensitivity'][condition]\n    config=read(HERE/(family+'-original.json'));seed=")
s=s.replace("evaluation_role='inner_validation' if pilot else 'outer_evaluation')","evaluation_role='inner_validation' if pilot else 'outer_evaluation',assumed_label=variant['label'],external_loss_multiplier=variant['weight'])")
s=s.replace("if condition.startswith('B_'):yy[owners>=1061]=100","if condition.startswith('B_'):\n        yy[owners>=1061]=variant['label']\n        weights=weights.copy();weights[np.repeat(owners>=1061,2)]*=variant['weight']")
s=s.replace("default='A,B_adult,B_child,C,D_adult,D_child'", "default='"+','.join(conds)+"'")
path.write_text(s,encoding='utf-8')
slurm=(HERE/'bundle/submit.slurm').read_text();slurm=slurm.replace('gdi-masked-pretrain','normal-label-sensitivity')
slurm=slurm.replace('experiment.py train --family "$family" --device cuda','experiment.py train --family "$family" --conditions '+','.join(p['main_conditions'])+' --device cuda')
(HERE/'bundle/submit.slurm').write_text(slurm,encoding='utf-8')
ops=(OLD/'ops.py').read_text().replace('20261105-gdi-masked-pretrain-v3','20261105-normal-label-sensitivity').replace('gdi-masked-pretrain-v3-20261105','normal-label-sensitivity-20261105').replace('masked_pretrain_then_gdi','assumed_label_loss_sensitivity').replace('expected_main_fits=60,expected_pretraining_fits=30','expected_main_fits=40,expected_pretraining_fits=0')
ops=ops.replace("assert read(HERE/'preflight.json')['passed'];", "BIG.mkdir(parents=True,exist_ok=True)\n    assert read(HERE/'preflight.json')['passed'];")
ops=ops.replace("        z.write(BIG/'data.npz','data.npz')", "        # Existing approved data is reused on the same server; code-only archive.")
ops=ops.replace("sha(BIG/'data.npz')", "sha(Path('D:/gait-research-data/D_P/gdi-masked-pretrain-v3-20261105/data.npz'))")
ops=ops.replace("(root/'logs').mkdir();os.chdir(root)","(root/'data.npz').symlink_to('/abr/RESEARCH_USER/gdi-masked-pretrain-v3-20261105/data.npz')\n(root/'logs').mkdir();os.chdir(root)")
ops=ops.replace("for condition in ['A','B_adult','B_child','C','D_adult','D_child']:","for condition in json.loads((root/'protocol.json').read_text())['conditions']:")
ops=ops.replace('mask-pilot-','sensitivity-pilot-').replace('mask-main-','sensitivity-main-')
ops=ops.replace("contains='Existing approved deidentified feature data and coordinate observation masks; model/code; no RGB video.'", "contains='Code-only archive. Existing approved v3 data reused on same server, hash checked; no new participant data.'")
(HERE/'ops.py').write_text(ops,encoding='utf-8')
audit=(OLD/'audit.py').read_text().replace("default='A,B_adult,B_child,C,D_adult,D_child'", "default='"+','.join(conds)+"'")
audit=audit.replace("assert done['identity']==ident", "assert ident['assumed_label']==p['sensitivity'][condition]['label'] and ident['external_loss_multiplier']==p['sensitivity'][condition]['weight']\n    assert done['identity']==ident")
(HERE/'audit.py').write_text(audit,encoding='utf-8')
init=(OLD/'initialization_replay.py').read_text().replace('gdi-masked-pretrain-v3-20261105','normal-label-sensitivity-20261105')
(HERE/'initialization_replay.py').write_text(init,encoding='utf-8')
print(HERE)
